// Yardımcı: bir modülün belirli bir tür için havuzu var mı, varsa döndür.
export function getModulePracticePool(moduleId, type) {
  return modulePractice[moduleId]?.[type] || [];
}

// Bu modül için hangi türlerde elle yazılmış içerik hazır?
export function hasModulePractice(moduleId) {
  return Boolean(modulePractice[moduleId]);
}
